WITH payload AS (SELECT $archive_payload$[{"id":"4937cf97-af06-58e2-b456-3bb8e652f78f","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -انحراف وانقاب سيارة -تبليغ املدعى عليه مبوعد اجللسة مرتن لغير شخصه -السير يف نظر الدعوى -تقرير اللجنة املش كلة للحادث -شهادة الشهود -إدانة شركة صيانة الطرق لعدم وجود لوحات إرشادية -تقدير أهل اخلبرة لقيمة التلفيات -تخ لف املدعى عليه عن احلضور رغم تبليغه يعد نكو ال عن اجلواب -اإللزام بدفع األرش املتيقن نظير تلفيات سيارة","document_number":"33448197","case_number":"33176332","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بسكاكا /املكلف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/9","year":"1434","subject":"حادث مروري -انحراف وانقاب سيارة -تبليغ املدعى عليه مبوعد اجللسة مرتن لغير شخصه -السير يف نظر الدعوى -تقرير اللجنة املش كلة للحادث -شهادة الشهود -إدانة شركة صيانة الطرق لعدم وجود لوحات إرشادية -تقدير أهل اخلبرة لقيمة التلفيات -تخ لف املدعى عليه عن احلضور رغم تبليغه يعد نكو ال عن اجلواب -اإللزام بدفع األرش املتيقن نظير تلفيات سيارة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/11/9 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33448197 :‬‬\n                         ‫َر ْق ُم الدعوى‪33176332 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34269982‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬انحــراف وانقــاب ســيارة ‪ -‬تبليــغ املدعــى عليــه مبوعــد‬\n     ‫اجللســة مرتــن لغيــر شــخصه ‪ -‬الســير يف نظــر الدعــوى ‪ -‬تقريــر‬\n     ‫اللجنــة املشـ ّـكلة للحــادث ‪ -‬شــهادة الشــهود ‪ -‬إدانــة شــركة صيانــة‬\n     ‫الطــرق لعــدم وجــود لوحــات إرشــادية ‪ -‬تقديــر أهــل اخلبــرة لقيمــة‬\n     ‫التلفيــات ‪ -‬تخ ّلــف املدعــى عليــه عــن احلضــور رغــم تبليغــه يعــد نكــو ًال‬\n     ‫عــن اجلــواب ‪ -‬اإللــزام بدفــع األرش املتيقــن نظيــر تلفيــات ســيارة‬\n                                                                              ‫املدعــي‪.‬‬\n\n\n\n\n                                     ‫‪ -1‬قاعدة ‪ :‬األقل يف تقدير األرش هو املتيقن ‪.‬‬\n                                        ‫‪ -2‬قاعدة ‪ :‬الناكل يقضى عليه بالنكول ‪.‬‬\n                         ‫‪ -3‬املادة (‪ )2/55‬من نظام املرافعات الشرعية والئحته ‪.‬‬\n\n\n\n\n     ‫حضــر املدعــي وكالــة ولــم يحضــر وكيــل الشــركة املدعــى عليهــا‬\n     ‫رغــم تبلــغ مديــر اإلدارة القانونيــة مرتــن لــذا قــررت احملكمــة الســير‬\n     ‫يف نظــر الدعــوى ‪ -‬قــرر املدعــي وكالــة بأنــه وقــع حــادث انحــراف‬\n     ‫وانقــاب خــارج الطريــق لســيارة موكلــه وانتهــى التحقيــق إلــى إدانــة‬\n     ‫الشــركة املكلفــة بصيانــة الطريــق بنســبة ‪ %75‬كمــا أديــن املدعــي‬\n\n‫‪53‬‬\n\f‫اصالــة بنســبة ‪ - %25‬نتــج عــن احلــادث تلفيــات بســيارة املدعــي ‪ -‬طلــب‬\n‫املدعــي وكالــة إلــزام الشــركة املدعــى عليهــا بدفــع أرش التلفيــات ‪-‬‬\n‫جــرى الرجــوع إلــى تقريــر اللجنــة املشــكلة لهــذا احلــادث وقــد جــاء فيــه‬\n‫أن اللجنــة انتهــت إلــى أن مســؤولية قائــد املركبــة (املدعــى أصالــة)‬\n‫عــن احلــادث موضــوع التحقيــق بنســبة ‪ %25‬وذلــك لتجــاوزه حــد الســرعة‬\n‫املســموح بــه للســير علــى ذلــك الطريــق ‪ -‬إدانــة الشــركة املدعــى عليهــا‬\n‫بنســبة ‪ %75‬وذلــك لإلهمــال املتمثــل يف عــدم اتخاذهــا أيــا مــن إجــراءات‬\n‫األمــن والســامة الواجــب اتخاذهــا للتحذيــر وتنبيــه ســالكي الطريــق‬\n‫مــن أعمــال الصيانــة املنفــذة عليــه ‪ -‬احضــر املدعــي وكالــة شــاهدين‬\n‫شــهدا بعــدم وضــع الشــركة املدعــى عليهــا أثنــاء وقــوع احلــادث ألي‬\n‫لوحــة إرشــادية علــى وجــود أعمــال الصيانــة‪ -‬جــرى تعديــل الشــاهدين‬\n‫‪ -‬جــرى الرجــوع إلــى تقديــر أرش التلفيــات وجــرى األخــذ باألقــل ألنــه‬\n‫املتيقــن ‪ -‬صــدر احلكــم بإلــزام الشــركة املدعــى عليهــا بدفــع أرش‬\n‫تلفيــات ســيارة املدعــي أصالــة ‪ -‬جــرى تعديــل الشــاهدين بعــد مالحظــة‬\n     ‫محكمــة االســتئناف ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬    ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة‬\n‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بســكاكا‪ /‬املكلــف برقــم ‪ 33176332‬وتاريــخ ‪1433/03/12‬‬            ‫ّ‬\n‫هـ املقيدة باحملكمة برقم ‪ 33446027‬وتاريخ ‪ 1433/03/08‬هـ ففي‬\n‫يــوم األحــد املوافــق‪ 1433/03/27‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪...‬‬\n‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ...‬الوكيــل عــن ‪ ...‬ســعودي‬\n\n                                                                                    ‫‪54‬‬\n\f     ‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n     ‫كتابــة عــدل ســكاكا برقــم ‪ 440504030485‬يف ‪1433/1/30‬ه ـ‬\n     ‫ولــم يحضــر منــدوب الشــركة املدعــى عليهــا وال مــن ميثلهــا وقــد تبلــغ‬\n     ‫‪ ...‬بصفتــه مديــر اإلدارة ‪ ...‬القانونيــة بشــركة ‪ ...‬حســب اخلطــاب الــوارد‬\n     ‫إلينــا مــن إدارة محضــري اخلصــوم بهــذه احملكمــة برقــم ‪33528694‬‬\n     ‫يف ‪1433/3/20‬ه ـ ولــذا فقــد قــررت تأجيــل اجللســة ثــم يف يــوم األحــد‬\n     ‫املوافــق‪ 1433/04/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n     ‫ولــم يحضــر منــدوب الشــركة املدعــى عليهــا وال مــن ميثلهــا وقــد تبلــغ ‪...‬‬\n     ‫بصفتــه مديــر ‪ ...‬اإلدارة القانونيــة بشــركة ‪ ...‬حســب اخلطــاب الــوارد‬\n     ‫إلينــا مــن إدارة محضــري اخلصــوم بهــذه احملكمــة برقــم ‪33659006‬‬\n     ‫يف ‪1433/4/7‬ه ـ ولكــون املدعــى عليــه تبلــغ لغيــر شــخصه ملرتــن فقــد‬\n     ‫قــررت ســماع الدعــوى فادعــى ‪ ...‬قائــا إنــه بتاريــخ ‪1432/2/9‬ه ـ وعلــى‬\n     ‫طريــق مغيــرا شــرق اللقائــط مبدينــة ســكاكا وقــع حــادث انحــراف‬\n     ‫وانقــاب خــارج الطريــق لســيارة نــوع ‪ ....‬بقيــادة موكلــي وانتهــى‬\n     ‫التحقيــق املــروري مبشــاركة هيئــة التحقيــق واالدعــاء العــام إلــى إدانــة‬\n     ‫املدعــى عليهــا شــركة ‪ ...‬بنســبة ‪ %75‬كمــا أديــن موكلــي بنســبة ‪%25‬‬\n     ‫وقــد نتــج عــن احلــادث حصــول تلفيــات بســيارة موكلــي وقــد قــدر أرش‬\n     ‫النقــص الــذي حلــق بســيارة موكلــي مــن قبــل معــارض الســيارات فقــدره‬\n     ‫معــرض ‪ ...‬مببلــغ واحــد وأربعــن ألــف ريــال ومعــرض ‪ ...‬قــدر األرش‬\n     ‫مببلــغ أربعــن ألــف وخمســمائة ريــال ومعــرض اســيا قــدره بأربعــن ألــف‬\n     ‫ريــال لــذا أطلــب إلزامــه واحلكــم عليــه بتســليم مــا يخصــه مــن األرش‬\n     ‫علــى ضــوء نســبة اإلدانــة املقــررة مــن املــرور هــذه دعــواي وبطلــب البينــة‬\n     ‫مــن املدعــي وكالــة أجــاب بقولــه هــي مــا يف أوراق املعاملــة ثــم جــرى‬\n\n\n‫‪55‬‬\n\f‫منــي اإلطــاع علــى تقريــر اللجنــة املشــكلة مــن هيئــة التحقيــق واالدعــاء‬\n‫العــام وإدارة مــرور منطقــة اجلــوف املشــكلة مبوجــب خطــاب ســعادة‬\n‫وكيــل إمــارة منطقــة اجلــوف رقــم ‪ 3241‬يف ‪1432/4/16‬ه ـ املتضمن أن‬\n‫بعــد إطــاع اللجنــة علــى كامــل أوراق القضيــة ودراســتها واســتكمال‬\n‫جميــع إجــراءات التحقيــق والوصــول إلــى نتائجهــا وبعــد اإلطــاع علــى‬\n‫نظــام املــرور الصــادر باملرســوم امللكــي رقــم ‪/85‬م يف ‪1428/10/26‬ه ـ‬\n‫فــإن اللجنــة تنتهــي إلــى مــا يلــي ‪1‬ـ مســئولية قائــد املركبــة املدعــو ‪...‬‬\n‫عــن احلــادث موضــوع التحقيــق بنســبة ‪ %25‬وذلــك لعــدم مراعــاة األنظمــة‬\n‫املتمثــل يف جتــاوز حــد الســرعة القصــوى املســموح بهــا للســير علــى ذلــك‬\n‫الطريــق وفقــا ملــا نصــت عليــه املــادة ‪ 60‬مــن نظــام املــرور املذكــور ‪2‬ـ‬\n‫مســؤولية شــركة ‪ ...‬عــن احلــادث موضــوع التحقيــق بنســبة ‪ %75‬وذلــك‬\n‫لإلهمــال املتمثــل يف عــدم اتخاذهــا أيــا مــن اإلجــراءات األمــن والســامة‬\n‫الواجــب اتخاذهــا للتحذيــر وتنبيــه ســالكي الطريق مــن أعمال الصيانة‬\n‫املنفــذة عليــه وفقــا ملــا نصــت عليــه املــادة ‪ 60‬مــن نظــام املــرور املشــار إليــه‬\n‫وبــاهلل التوفيــق عضــو اللجنــة‪ ... /‬منــدوب إدارة مــرور منطقــة اجلــوف و ‪...‬‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام أ‪.‬ه ـ وبطلــب زيادة البينــة طلب مهلة‬\n‫إلحضارهــا ورفعــت اجللســة ثــم يف يــوم الثالثــاء املوافــق‪1433/05/25‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ولــم يحضــر منــدوب‬\n‫الشــركة املدعــى عليهــا وقــد جــرى تبليــغ الشــركة املدعــى عليهــا‬\n‫مبوعــد اجللســة مبوجــب خطــاب التبليــغ املرفــق باملعاملــة ثــم جــرى منــا‬\n‫ســؤال املدعــي وكالــة عمــا وعــد بــه يف اجللســة الســابقة فأجــاب بقولــه‬\n‫إن بينتــي معــي ويف نفــس اجللســة حضــر الشــاهد ‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ...‬مــن العمــر ‪ 34‬عامــا ويعمــل يف الهــال‬\n\n\n                                                                                              ‫‪56‬‬\n\f     ‫األحمــر الســعودي وال تربطــه باملدعــي صلــة قرابــة وجــرى ســؤاله عمــا‬\n     ‫لديــه فأجــاب بقولــه إننــي أعمــل يف الهــال األحمــر الســعودي وقــد‬\n     ‫وصلــت ملــكان احلــادث بعــد نصــف ســاعة مــن وقــوع احلــادث ولــم أجــد أي‬\n     ‫عالمــات حتذيــره للطريــق حيــث أن الطبقــة العلويــة مــن اإلســفلت متــت‬\n     ‫إزالتهــا وقــد وقــع احلــادث يف منعطــف وبعــده تنتهــي أعمــال الســفلتة وال‬\n     ‫يوجــد أي لوحــات حتذيريــه هــذا مــا لــدي كمــا حضــر يف نفــس اجللســة‬\n     ‫الشــاهد الثانــي ‪ ...‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ...‬ويبلــغ‬\n     ‫مــن العمــر ‪ 28‬عام ـ ًا وجــرى ســؤاله عــن صلــة قرابتــه باملدعــي وكالــة‬\n     ‫أو أصالــة فأجــاب بقولــه أنــه شــقيق والدتــي ثــم جــرى ســؤاله عمــا لديــه‬\n     ‫فأجــاب بقولــه إننــي كنــت برفقــة املدعــي أصالــة حيــث وقــع احلــادث‬\n     ‫وكان الوقــت مســاء وبعــد أحــد املنعطفــات انقطــع اإلســفلت بشــكل‬\n     ‫مفاجــئ وبــدون عالمــات إرشــادية أو لوحــات حتذيريــه ممــا تســبب يف‬\n     ‫وقوع احلادث هذا ما لدي وحضر للتزكية كل من ‪ ...‬سعودي اجلنسية‬\n     ‫مبوجــب ســجل مدنــي رقــم ‪ ...‬و‪ ...‬ســعودي اجلنســية مبوجــب ســجل مدنــي‬\n     ‫رقــم ‪ ...‬وقــررا مبعرفتهمــا للشــاهدين وصالحيتهمــا للشــهادة والنتهــاء‬\n     ‫وقــت اجللســة رفعــت ثــم يف يــوم اإلثنــن املوافــق‪ 1433/11/08‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه‬\n     ‫وقــد تبلــغ لغيــر شــخصه ألكثــر مــن مــرة حيــث تبلــغ مبوعــد اجللســة‬\n     ‫املقــررة بتاريــخ ‪1433/9/17‬ه ـ وقــد تبلــغ باملوعــد عــن طريــق ‪ ...‬بصفتــه‬\n     ‫مديــر اإلدارة القانونيــة حســب خطــاب التبليــغ الــوارد إلينــا مــن قســم‬\n     ‫احملضريــن برقــم ‪ 331704999‬يف ‪1433/9/13‬ه ـ كمــا تبلــغ مبوعــد‬\n     ‫اجللســة املقــررة بتاريــخ ‪1433/10/21‬ه ـ وقــد تبلــغ باملوعــد عــن طريــق ‪...‬‬\n     ‫بصفتــه ســكرتير إدارة املــوارد البشــرية حســب خطــاب التبليــغ الــوارد‬\n\n\n‫‪57‬‬\n\f‫إلينــا مــن قســم احملضريــن برقــم ‪ 33181560‬يف ‪1433/10/18‬ه ـ‬\n‫كمــا تبلــغ مبوعــد هــذه اجللســة وقــد تبلــغ باملوعــد عــن طريــق ‪ ...‬بصفتــه‬\n‫مديــر املاليــة حســب خطــاب التبليــغ الــوارد إلينــا مــن قســم احملضريــن‬\n‫برقــم ‪ 331882349‬يف ‪1433/10/24‬ه ـ وبنــاء علــى املــادة اخلامســة‬\n‫عشــر واملــادة الثامنــة عشــر فقــرة ج مــن نظــام املرافعــات الشــرعية فقــد‬\n‫قــررت مواصلــة ســماع الدعــوى وجــرى ســؤال املدعــي وكالــة هــل لديــه‬\n‫مــا يضيفــه فأجــاب بالنفــي وأغلــق بــاب املرافعــة وبعــد ســماع الدعــوى‬\n‫واإلطــاع علــى أوراق املعاملــة ومنهــا احملضــر اخلــاص بكيفيــة وقــوع‬\n‫احلــادث املتضمــن مــا جــاء بدعــوى املدعــي وكالــة وكذلــك التقريــر‬\n‫الصــادر مــن اللجنــة املشــكلة مــن هيئــة التحقيــق واالدعــاء العــام وإدارة‬\n‫مــرور منطقــة اجلــوف املتضمــن أن بعــد إطــاع اللجنــة علــى كامــل أوراق‬\n‫القضيــة ودراســتها واســتكمال جميــع إجــراءات التحقيــق والوصــول‬\n‫إلــى نتائجهــا وبعــد اإلطــاع علــى نظــام املــرور الصــادر باملرســوم‬\n‫امللكــي رقــم ‪/85‬م يف ‪1428/10/26‬ه ـ فــإن اللجنــة تنتهــي إلــى مــا يلــي‬\n‫‪1‬ـ مســؤولية قائــد املركبــة املدعــو ‪ ...‬عــن احلــادث موضــوع التحقيــق‬\n‫بنســبة ‪ %25‬وذلــك لعــد مراعــاة األنظمــة املتمثــل يف جتــاوز حــد الســرعة‬\n‫القصــوى املســموح بهــا للســير علــى ذلــك الطريــق وفقــا ملــا نصــت عليــه‬\n‫املــادة ‪ 60‬مــن نظــام املــرور املذكــور ‪2‬ـ مســؤولية شــركة ‪..............‬‬\n‫عــن احلــادث موضــوع التحقيــق بنســبة ‪ %75‬وذلــك لإلهمــال املتمثــل يف‬\n‫عــدم اتخاذهــا أيــا مــن اإلجــراءات األمــن والســامة الواجــب اتخاذهــا‬\n‫للتحذيــر وتنبيــه ســالكي الطريــق مــن أعمــال الصيانــة املنفــذة عليــه‬\n‫وفقــا ملــا نصــت عليــه املــادة ‪ 60‬مــن نظــام املــرور املشــار إليــه أ‪.‬ه ـ وبعــد‬\n‫ســماع شــهادة الشــهود املتضمنــة وصــف احلــادث وعــد اتخــاذ الشــركة‬\n\n\n                                                                                          ‫‪58‬‬\n\f     ‫املدعــى عليهــا لالحتياطــات النظاميــة وبعــد اإلطــاع علــى تقديــر‬\n     ‫أرش التلفيــات بالســيارة املذكــورة أعــاه بــن قيمتهــا ســليمة وتالفــة‬\n     ‫مــن أهــل اخلبــرة أصحــاب معــارض الســيارات وهــم بــا شــك أصحــاب‬\n     ‫خبــرة ونظــر يف مثــل هــذه األمــور ولهــم معرفــة يف تقديرهــا ألن مــن‬\n     ‫املقــرر شــرع ًا اعتبــار رأي أهــل اخلبــرة مــا لــم يظهــر قــادح مؤثــر وحيــث‬\n     ‫اختلــف أهــل اخلبــرة يف تقــومي األرش وألن تقديــر األرش بأربعــن ألفــا‬\n     ‫هــو األقــل واملتيقــن خصوصــا مــع تقــارب التقديــرات وقلــة الفــارق بينهــا‬\n     ‫وألن نســبة إدانــة الشــركة هــو ‪ %75‬مــن قيمــة التلفيــات وألن الشــركة‬\n     ‫املدعــى عليهــا تبلغــت مبوعــد اجللســة ولــم يحضــر مديرهــا أو مندوبــه‬\n     ‫ولــم يعتــذر عــن احلضــور ولــم يقــدم دفاعــه والن عــدم حضــوره مــع تبلغــه‬\n     ‫لغيــر شــخصه مبوعــد اجللســة يعــد نكــو ًال عــن اجلــواب والنــاكل يقضــى‬\n     ‫عليــه بالنكــول‪ ،‬وألن احلكــم يعــد غيابيــا بحــق املدعــى عليــه الغائــب‬\n     ‫الــذي تبلــغ لغيــر شــخصه مبوعــد اجللســة حســب املــادة ‪ 2/55‬مــن نظــام‬\n     ‫املرافعــات الشــرعية لــذ فقــد حكمــت بإلــزام املدعــى عليهــا شــركة‬\n     ‫‪ ... ...‬أن تســلم للمدعــي وكالــة مبلغــا وقــدره ثالثــون ألــف ريــال بحســب‬\n     ‫نســبة إدانتهــا مــن قيمــة تلفيــات الســيارة املقــدرة بأربعــن ألــف ريــال‬\n                          ‫وبعــرض احلكــم علــى املدعــي وكالــة قنــع بــه وقــررت‬\n     ‫بعــث صــورة مــن صــك احلكــم للمدعــى عليهــا لتقــدم االعتــراض خــال‬\n     ‫مــدة ثالثــن يومـ ًا مــن تاريــخ االســتالم ‪،‬فــإذا لــم يقــدم اعتراضـ ًا خــال‬\n     ‫هــذه املــدة ســقط حقــه يف طلــب االســتئناف و اكتســب احلكــم القطعية‬\n     ‫حســب املــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪ 1433/11/09‬ه ـ‬\n\n\n‫‪59‬‬\n\f‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بســكاكا‬\n‫الشــيخ‪ .../‬برقم‪34397030‬وتاريخ‪1434/6/17‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة الشــيخ‪ .../‬برقــم ‪33448197‬وتاريخ‪1433/11/9‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي ‪ ...‬ضد‪/‬شــركة ‪ ... ...‬يف قضيــة حــادث مــروري‬\n‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة فقــد تقــرر املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                        ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪60‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":53,"source_page_end":60,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f82d84840080be5da3c7b78d0858e94f5d2e2a753ed1aec6bf21ed48f6555ab4","normalized_text_hash":"b6ced5c515422b1a4808ddef1251296a74897396097584ac1b6912d998f2ecd3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p53-33448197"},{"id":"2c1d864d-016e-5d43-a283-5d090fe70988","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -سبب احلادث إبل سائبة -مطالبة بقيمة تلفيات سيارة -مصادقة املدعي على وقوع احلادث نهار ا -عدم أخذ القاضي برأي أهل اخلبرة ملوجب شرعي -ال ضمان على رب البهيمة فيما تفسده نهار ا مطلق ا -رد الدعوى وإخاء سبيل املدعى عليه منها .","document_number":"33480601","case_number":"33324274","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة القائم بعمل املكتب القضائي الثالث بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"حادث مروري -سبب احلادث إبل سائبة -مطالبة بقيمة تلفيات سيارة -مصادقة املدعي على وقوع احلادث نهار ا -عدم أخذ القاضي برأي أهل اخلبرة ملوجب شرعي -ال ضمان على رب البهيمة فيما تفسده نهار ا مطلق ا -رد الدعوى وإخاء سبيل املدعى عليه منها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/12/28 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33480601 :‬‬\n                          ‫َر ْق ُم الدعوى‪33324274 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                    ‫‪ 3453996‬تاريخه‪1434/3/3 :‬هـ‬\n\n\n       ‫حــادث مــروري‪ -‬ســبب احلــادث إبــل ســائبة‪ -‬مطالبــة بقيمــة تلفيــات‬\n       ‫ســيارة‪ -‬مصادقــة املدعــي علــى وقــوع احلــادث نهــار ًا‪ -‬عــدم أخــذ القاضــي‬\n       ‫بــرأي أهــل اخلبــرة ملوجــب شــرعي‪ -‬ال ضمــان علــى رب البهيمــة فيمــا‬\n       ‫تفســده نهــار ًا مطلقـ ًا‪ -‬رد الدعــوى وإخــاء ســبيل املدعــى عليــه منهــا ‪.‬‬\n\n\n\n\n         ‫‪ -1‬قوله صلى اهلل عليه وسلم‪« :‬العجماء جرحها جبار»متفق عليه ‪.‬‬\n       ‫‪ -2‬ان الرســول صلى اهلل عليه وســلم «قضى على أهل األموال حفظها‬\n             ‫بالنهــار وعلــى أهــل املواشــي حفظهــا بالليــل» رواه أبو داود وابن ماجه‬\n       ‫‪ -3‬مــا قــرره الفقهــاء مــن أنــه ال ضمــان علــى مالــك البهيمــة فيمــا‬\n       ‫تفســده نهــارا مطلق ـ ًا ‪ -‬شــرح منتهــى اإلرادات ‪ - 338/2‬كشــاف‬\n       ‫الق ـ ـن ـ ــاع ‪ - 371/2‬بـدايـ ـ ـ ــة املجتهــد ‪ - 242/2‬منهــاج ال ـ ــطالب ــن مـ ـ ــع‬\n                                      ‫مغـ ــنى احملـ ـتـ ـ ــاج ‪ 206/4‬وال ـ ـ ــفروع (‪.)521/4‬‬\n       ‫‪ -4‬ومــا قــرره أهــل العلــم ‪ :‬مــن أن غيــر الــزرع يلحــق بالــزرع أيض ـ ًا يف‬\n       ‫هــذا احلكــم ‪ ،‬انظــر‪ :‬حاشــية الشــرقاوي علــى التحريــر مــن الشــافعية‬\n                     ‫(‪ ،)447 - 446/1‬وصاحــب الفــروع مــن احلنابلــة (‪. )521/4‬‬\n\n\n\n\n‫‪61‬‬\n\f‫دعــوى املدعــي وكالــة بــأن الســائق اخلــاص بــه كان يقــود الســيارة‬\n‫اخلاصــة باملدعيــة أصالــة ثــم اصطدم يف ســيارة شــخص وذلــك لوجود إبل‬\n‫ســائبة عائــدة للمدعــى عليــه وتســبب هــذا احلــادث يف تلفيــات يف ســيارة‬\n‫املدعيــة أصالــة وقــد أديــن املدعــى عليــه بنســبة اخلطــأ ‪ %75‬واديــن ســائق‬\n‫املدعــى بنســبة ‪ %25‬وحيــث أن ســبب احلــادث وجــود إبــل ســائبة مبوجــب‬\n‫تقريــر املــرور وقــدرت تلفيــات الســيارة اخلاصــة باملدعيــة مبلغ ـ ًا قــدره‬\n‫خمســة وأربعــون ألــف ريــال وطالــب املدعــي وكالــة بإلــزام املدعــى عليــه‬\n‫حيــث انــه صاحــب اإلبــل بقيمــة التلفيــات التــي حدثــت بســيارة موكلتــه‬\n‫حســب نســبة اخلطــأ التــي عليــه ‪ -‬صــادق املدعــى عليــه علــى الدعــوى‬\n‫وقــرر معارضتــه علــى تقريــر املــرور وأن ابلــه ال عالقــة لهــا باحلــادث ‪-‬‬\n‫جــرى اطــاع حاكــم القضيــة علــى تقريــر املــرور فوجــده كمــا ذكــر‬\n‫املدعــي وكالــة وان احلــادث يف النهــار ‪ -‬قــرر ناظــر القضيــة أنــه نظــر ًا‬\n‫ألن احلــادث يف النهــار وســائق املدعــي مباشــر للحــادث ويســير بســرعة‬\n‫زائــدة عــن احلــد املســموح وملــا قــرره الفقهــاء مــن أنــه ال ضمــان علــى مالــك‬\n‫البهيمــة فيمــا تفســده نهــارا مطلق ـ ًا وملــا جــاء يف أســباب احلكــم فقــد‬\n‫صــدر احلكــم بــرد الدعــوى ‪ -‬قــرر املدعــي وكالــة املعارضــة ‪ -‬صــدر‬\n                      ‫قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                          ‫‪62‬‬\n\f     ‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق ‪1432/2/5‬ه ـ لــدي أنــا‬\n     ‫القاضــي باحملكمــة العامــة بعنيــزة القائــم بعمــل املكتــب القضائــي‬\n     ‫الثالــث بنــاء علــى تكليــف فضيلــة الرئيــس رقــم ‪ 31/12455‬يف‬\n     ‫‪1431/7/3‬ه ـ افتتحــت اجللســة بوقتهــا احملــدد لســماعها الســاعة‬\n     ‫احلاديــة عشــر صباحــا للنظــر بالدعــوى املقدمــة مــن هنــدي ضــد واملقيــدة‬\n     ‫باحملكمــة برقــم ‪ 3114530‬يف ‪1431/8/6‬ه ـ واحملالــة لنــا بشــرح‬\n     ‫فضيلــة الرئيــس وفيهــا حضــر ســعودي بالســجل رقــم الوكيــل عــن‬\n     ‫ســعودية بالســجل املدنــي رقــم مبوجــب الوكالــة الصــادرة مــن كاتــب‬\n     ‫عــدل بريــدة برقــم ‪ 4316‬يف ‪1430/1/24‬ه ـ وادعــى علــى احلاضــر‬\n     ‫ســعودي بالســجل املدنــي رقــم قائــا يف حتريــر دعــواه لقــد كان‬\n     ‫الســائق اخلــاص بــي أنــا يقــود ســيارة موكلتــي وهــي مــن نــوع مرســيدس‬\n     ‫رأس لونهــا أخضــر صنــع عــام ‪1982‬م رقــم لوحتهــا‪ ...‬يف طريــق املدينــة‬\n     ‫الريــاض الســريع يف طريــق اخلدمــة ثــم اصطــدم يف ســيارة شــخص يدعى‬\n     ‫وقــد تســبب هــذا احلــادث يف تلفيــات يف ســيارة موكلتــي وقــد أديــن‬\n     ‫املدعــى عليــه بنســبة خمســة وســبعني باملائــة مــن اخلطــأ يف هــذا احلــادث‬\n     ‫وأديــن ســائق موكلتــي بنســبة خمســة وعشــرين باملائــة مــن نســبة اخلطــأ‬\n     ‫يف هــذا احلــادث وذلــك نظــرا ألن ســبب احلــادث هــو وجــود إبــل ســائبه‬\n     ‫يف طريــق اخلدمــة املذكــور وقــد صــدر بذلــك تقريــر اجلهــة املختصــة‬\n     ‫بذلــك لــدى املــرور رقــم بــدون يف ‪1431/3/21‬ه ـ وقــد قــدرت تلفيــات‬\n     ‫ســيارة موكلتــي بقيمــة مقدارهــا خمســة وأربعــون ألــف ريــال أطلــب‬\n     ‫إلزامــه بدفــع النســبة التــي يتحملهــا وقدرهــا ثالثــة أربــاع هــذا املبلــغ وهــو‬\n\n‫‪63‬‬\n\f‫مبلــغ قــدره ثالثــة وثالثــون ألفــا وســبعمائة وخمســون ريــاال هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي وكالــة أجــاب قائــا‬\n‫مــا ذكــره املدعــي وكالــة مــن وقــوع احلــادث فهــذا صحيــح لكــن اجلمــل‬\n‫اململــوك لــي لــم يتســبب يف هــذا احلــادث ولــم يصدمــه أحــد بــل إن ســائق‬\n‫املدعيــة أصالــة واملدعــي همــا اللــذان تصادمــا وأمــا جملــي فــا عالقــة‬\n‫لــه بهــذا احلــادث ثــم رفعــت اجللســة النتهــاء الوقــت احملــدد لســماعها ويف‬\n‫يــوم الســبت املوافــق ‪1432/7/2‬ه ـ افتتحــت اجللســة يف الســاعة احلاديــة‬\n‫عشــر صباحــا وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه ثــم جــرى‬\n‫ســؤال املدعــي وكالــة عــن بينتــه علــى مــا جــاء يف دعــواه فقــال أن بينتــي‬\n‫هــي تقريــر جلنــة املــرور املعــد بتاريــخ ‪1431/3/21‬ه ـ واطلــب تدوينهــا‬\n‫بضبــط القضيــة ثــم جــرى االطــاع علــى التقريــر املشــار إليــه املرفــق‬\n‫باملعاملــة لفــة (‪ )26‬و وجدتــه يتضمــن إدانــة صاحــب اجلمــل بنســبة ‪%75‬‬\n‫مــن نســبة احلــادث نظــرا لتركــه لإلبــل ســائبه قــرب طريــق مخصــص‬\n‫للســيارات بــدون عنايــة ولتعريضــه لآلخريــن للخطــر ولوقــوع احلــادث يف‬\n‫وضــح النهــار ممــا يــدل علــى عــدم أخــذ احليطــة واحلــذر مــن قبــل صاحــب‬\n‫اإلبــل كمــا يــدان قائــد الســيارة بالشــكل الصحيــح ممــا يــدل علــى قلــة‬\n‫االحتــراز ونظــرا لســرعته الزائــدة ممــا يــدل علــى عــدم تقيــده باألنظمــة‬\n‫محقــق احلــادث ‪ .......‬توقيعــه عضــو توقيعــه عضــو توقيعــه رئيــس اللجنــة‬\n‫توقيعــه أ‪.‬هــ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا اننــي ال‬\n‫عالقــة لــي بهــذا احلــادث جملــة وتفصيــا ألننــي لســت مباشــر للحــادث‬\n‫وال متســبب فيــه نظــرا ألنــه لــم يصطــدم وهــو ســائق الفــورد بناقتــي‬\n‫وليــس هنــاك مــا يثبــت اعتراضــه لــه يف الطريــق ســوى إفــادة منــه لــدى‬\n‫جهــة التحقيــق وهــذه ليســت بشــهادة ألنــه طــرف يف هــذا احلــادث ويريــد‬\n\n\n                                                                                     ‫‪64‬‬\n\f     ‫بذلــك أن يدفــع عــن نفســه ضــرر ويجــر لنفســه نفــع وان تقريــر املــرور‬\n     ‫فقــد بنــي علــى هــذه اإلفــادة ولــم يتعــرض ال ثبــات تســبب ناقتــي فيــه‬\n     ‫مــن عدمــه وعلــى فــرض أن مــا ذكــره صحيــح فــإن جنايــة احليــوان هــدر‬\n     ‫لقولــه صلــى اهلل عليــه وســلم (العجمــاء جرحهــا جبار) ولــذا فأنني اطلب‬\n     ‫رد هــذه الدعــوى وقــد قــدم رده يف ورقــة واحــدة مت ضمهــا للمعاملــة ثــم‬\n                                                                    ‫رفعــت اجللســة‪.‬‬\n     ‫ويف يــوم االثنــن املوافــق‪ 1433/05/10‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة‪ 09:10‬وفيهــا حضــر املدعــي وكالــة ســعودي مبوجــب الســجل‬\n     ‫املدنــي رقــم ولــم يحضــر املدعــي وقــد وردنــا خطــاب قســم اإلحضــار يف‬\n     ‫هــذه احملكمــة رقــم ‪ 33783212‬تاريــخ ‪1433/4/26‬ه ـ املتضمــن أنــه‬\n     ‫مت االتصــال باملدعــى عليــه هاتفي ـ ًا وذكــر أنــه يســكن يف قريــة تابعــة‬\n     ‫حملكمــة العظيــم بحائــل وقــد جــرى إرســال خطــاب رســمي للشــرطة‬\n     ‫برقــم ‪ 33783212‬بتاريــخ ‪1433/5/1‬ه ـ إلبــاغ املدعــى عليــه باملوعــد‬\n     ‫ولــم تــرد اإلفــادة حتــى اآلن وجــرى تــاوة مــا مت ضبطــه للمدعــي وكالــة‬\n     ‫فصــادق علــى صــدوره منــه وأضــاف قائــا‪ :‬أننــي ســبق أن وافقــت علــى‬\n     ‫حتمــل موكلــي نســبة ‪ %25‬مــن اخلطــاء ولكــن اآلن ومــع طــول املــدة‬\n     ‫فأننــي اعتــرض علــى تقريــر املــرور فــإن موكلــي ال يتحمــل أي مســؤولية‬\n     ‫بخصــوص هــذا احلــادث والــذي يتحمــل نســبة اخلمســة والعشــرين باملائــة‬\n     ‫مــن املســؤولية هــو صاحــب الســيارة الفــورد والباقــي مــن املســؤولية‬\n     ‫يتحملــه صاحــب اجلمــل‪ .‬هكــذا قــرر فســألته عــن كيفية وقــوع احلادث؟‬\n     ‫فقــال‪ :‬إن موكلــي كان يســير بالشــاحنة يف طريــق اخلدمــة يف طريــق‬\n     ‫الريــاض املدينــة الســريع وكانــت الســيارة الفــورد تســير أمامــه فشــاهد‬\n     ‫قائــد الســيارة الفــورد ناقــة علــى ميــن الطريــق باركه وبجوارهــا حوارها‬\n\n\n‫‪65‬‬\n\f‫الصغيــر وملــا ســمع احلــوار صــوت الســيارات قــام مــن عنــد امــه واعتــرض‬\n‫أمــام الســيارة الفــورد فقــام قائــد الفــورد بتخفيــف الســرعة وكانــت‬\n‫الســيارة الشــاحنة اخلاصــة بنــا خلفــه فلــم يســتطع قائدهــا التوقــف ألنهــا‬\n‫كانــت تســير يف منحــدر ومحمــل بالرمــل فصــدم الفــورد مــن اخللــف يف‬\n‫مقدمــة الشــاحنة ثــم انقلبــت يف نفــس الطريــق هكــذا قــرر‪ .‬فســألته هــل‬\n‫اصطدمــت الســيارة الفــورد باجلمــل املذكــور؟ فقــال‪ :‬ال أدري ولكــن‬\n‫األقــرب أن الشــاحنة ملــا اصطدمــت بالســيارة الفــورد انحرفــت فصدمــت‬\n‫اجلمــل املذكــور ويؤكــد هــذا أن مقدمــة الســيارة الفورد ليــس فيها أثار‬\n‫اصطــدام ممــا يــدل علــى أنهــا لــم تصــدم باجلمــل واطلــب إحضــار صاحب‬\n‫الســيارة الفــورد وإدخالــه يف هــذه القضيــة‪ ،‬هكــذا قــرر املدعــي وألن‬\n     ‫األمــر يتطلــب حضــور صاحــب الســيارة الفــورد لــذا رفعــت اجللســة ‪.‬‬\n‫ويف يــوم األحــد املوافق‪1433/07/13‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة وفيهــا حضــر املدعــي وكالــة ســعودي بالســجل رقــم وحضــر‬\n‫املدعــى عليــه ســعودي بالســجل رقــم وجــرى تــاوة مــا مت رصــده بحضــور‬\n‫الطرفــن فصادقــا عليــه وقــال املدعــى عليــه أطلــب إحضــار الطــرف‬\n‫الثالث الرتباطه بالقضية وأيضا فإن سيارة املدعي لم تصطدم بجملي‬\n‫ولــم يصطــدم بــه صاحــب الســيارة الفــورد واملتســبب يف احلــادث والســائق‬\n‫املســرع قائــد الشــاحنة يف طريــق اخلدمــة هــذا مــا لــدي وقــال املدعــي إن‬\n‫طلبــه إطالــة للقضيــة واملتســبب جملــه ألنــه وجــد يف اإلســفلت يف املســار‬\n‫األميــن ميــت وســبب مــوت احلاشــي هــو مــن التريلــة بســبب احلديــد املتطايــر‬\n‫منهــا ولــم يصدمــه صاحــب الفــورد هــذا مــا لــدي فرفعــت اجللســة لدراســة‬\n‫القضيــة ولطلــب ويف يــوم االثنــن املوافــق‪ 1433/11/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى‬\n\n\n                                                                                      ‫‪66‬‬\n\f     ‫عليــه وحضــر حلضورهمــا الطــرف الثالــث ســعودي بالســجل املدنــي رقــم‬\n     ‫ا أنــى كنــت أســير يف‬     ‫وبســؤاله عــن كيفيــة وقــوع احلــادث أجــاب قائ ـ ً‬\n     ‫طريــق اخلدمــة متجــه إلــى الشــرق مقابــل شــركة الكهربــاء والطريــق‬\n     ‫فيــه مرتفعــات ومنحــدرات وعنــد نزولــي يف أحــد املنحــدرات شــهدت‬\n     ‫ناقــة باركــة بجنــب الطريــق مــن جهــة اليمــن قريبه لإلســفلت وبجوارها‬\n     ‫حــوار فقــام احلــوار وقطــع طريــق اخلدمــة باجتــاه الســريع فهديــت الســرعة‬\n     ‫وكنــت أســير بســرعة ثمانــون تقريب ـ ًا وهديــت إلــى ســرعة أربعــن أو‬\n     ‫أقــل مــن أربعــن ثــم اصطدمــت بــي التريلــه مــن اخللــف ثــم شــهدت بعــد‬\n     ‫ذلــك احلــوار ميــت علــى اإلســفلت والســيارة التريلــه منقلبــة يف اإلســفلت‬\n     ‫أمــام ســيارتي وأمــام احلــوار وال أعلــم مــا هــو ســبب مــوت احلــوار هكــذا‬\n     ‫قــرر وبعــرض ذلــك علــى الطرفــن قــال املدعــي وكالــة مــا جــاء يف قــول‬\n     ‫الطــرف الثالــث صحيــح والســيارة بعــد االصطــدام انقلبــت وتفككــت‬\n     ‫وكانــت محملــه بالرمــل وأطلــب إلــزام املدعــى عليه بدفــع ‪ %75‬من أرش‬\n     ‫نقــص ســيارة موكلــي كمــا جــاء يف تقريــر املــرور وليــس لــدي ســوى‬\n     ‫ذلــك وبعرضــه علــى املدعــى عليــه قــال ليــس لــدي ســوى مــا ذكرتــه‬\n     ‫ســابقا فرفعــت اجللســة ويف يــوم اإلثنــن املوافــق‪ 1433/12/27‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وفيهــا حضــر املدعــي‬\n     ‫وكالــة ســعودي بالســجل رقــم وحضــر املدعــى عليــه ســعودي بالســجل‬\n     ‫رقــم فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة ونظــر ًا الن تقريــر اللجنــة‬\n     ‫املختصــة بتقريــر نســبة اإلدانــة يف إدارة املــرور إمنــا هــو إقــرار أهــل اخلبــرة‬\n     ‫وهــو ليــس مبلــزم للقاضــي وألن احليثيــات التــي بنــي عليهــا التقريــر ال‬\n     ‫توجــب إدانــة املدعــى عليــه بــأي نســبة مــن اخلطــأ بهــذا احلــادث نظــرا ألنــه‬\n     ‫جــاء فيــه أن احلــادث وقــع يف وضــح النهــار وقــد صــادق املدعــي علــى وقــوع‬\n\n\n‫‪67‬‬\n\f‫احلــادث يف النهــار كمــا جــاء فيــه أن الســائق الثانــي كان يســير بســرعة‬\n‫يحمــل إال ربــع النســبة مــن‬\n                            ‫زائــدة عــن احلــد املســموح بــه ومــع هــذا فإنــه لــم ّ‬\n‫اخلطــأ وألن ســائق املدعــي مباشــر للحــادث ونظــرا ملــا قــرره الفقهــاء مــن‬\n‫أنــه ال ضامــن علــى مالــك البهيمــة فمــا تفســده نهــارا مطالقــا أ‪.‬ه ـ جــاء‬\n‫ذلــك يف شــرح منتهــى اإلرادات ( ‪ )378/2‬وكشــاف القنــاع ( ‪)371/2‬‬\n‫وهــذا مأخــوذ مــن األحاديــث الــواردة يف هــذا البــاب وهــي احلديــث األول‬\n‫قولــه عليــه الصــاة والســام (( العجمــاء جرحهــا جبــار )) متفــق عليــه‬\n‫ومعنــى جبــار أي هــدر ال شــيء فيــه واحلديــث الثانــي أن الرســول صلــى‬\n‫اهلل عليــه وســلم (( قضــى أن علــى أهــل األمــوال حفظهــا بالنهــار وعلــى‬\n‫أهل املواشــي حفظها بالليل )) رواه أبو داود والنســائي وابن ماجه وقال‬\n‫عنــه األلبانــي رحمــة اهلل حديــث صحيــح وهــذا هــو مذهــب املالكيــة‬\n‫كمــا نــص عليــه يف بدايــة املجتهــد ( ‪ )242/2‬والشــافعية كمــا نــص‬\n‫عليــه يف منهــاج الطالبــن مــع مغنــي احملتــاج ( ‪ )206/4‬واحلنابلــة كمــا‬\n‫نــص عليــه يف الفــروع ( ‪ )521/4‬وهــذا هــو القــول الراجــح يف نظــري‬\n‫لقــوة أدلتــه ونظــرا ملــا قــرره أهــل العلــم أيضــا أن غيــر الــزرع يلحــق بالــزرع‬\n‫يف هــذا احلكــم حيــث نــص علــى ذلــك صاحــب حاشــية الزرقــاوي علــى‬\n‫التحريــر مــن الشــافعية ( ‪ )447 .446/1‬وصاحــب الفــروع مــن احلنابلــة (‬\n‫‪ )521/4‬نظــرا ألنــه ورد يف حديــث الناقــة التــي دخلــت حائــط وأفســدت‬\n‫فيــه وهــذا لفــظ عــام ممــا يــدل علــى أن القيــاس قيــاس صحيــح وهــذا‬\n‫يف حــال مباشــرة العجمــاء وهــي يف هــذه القضيــة لــم تباشــر لذلــك‬\n‫كلــه فقــد رددت دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه مــن هــذه‬\n‫الدعــوى وبذلــك حكمــت وبعرضــه احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة واملدعــي عــدم القناعــة وطلــب متكينــه مــن االعتــراض‬\n\n\n                                                                                            ‫‪68‬‬\n\f     ‫فأجبتــه لطلبــه ‪ .‬وأفهمتــه باملراجعــة بعــد عشــرة أيــام الســتالم نســخة‬\n     ‫مــن احلكــم وأن مــدة االعتــراض ثالثــون يــوم إذا لــم يقــدم الالئحــة‬\n     ‫خاللهــا ســقط حقــه يف االعتــراض واكتســب احلكــم للقطعيــة ففهــم‬\n     ‫ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n     ‫وســلم ‪ .‬حــرر يف ‪1433/12/27‬هــ‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n     ‫األربعــاء املوافــق ‪1434/4/3‬ه ـ أفتحــت اجللســة يف الســاعة العاشــرة‬\n     ‫صباحــا بنــاء علــى ورود املعاملــة مــن محكمــة االســتئناف بالقصيــم‬\n     ‫برقــم (‪ )34418045‬يف ‪1434/3/15‬ه ـ وبرفقهــا قــرار قضــاة محكمــة‬\n     ‫االســتئناف بالدائــرة اجلزائيــة الثانيــة رقم (‪ )3453996‬يف ‪1434/3/3‬هـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد‬\n     ‫وآلــه وصحبــه أجمعــن وللمعلوميــة حــرر يف ‪1434/4/3‬هــ‪ .‬احلم ــد‬\n     ‫هلل وح ــده وبعـد‪...‬فق ــد اطَّ لعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطق ــة القصي ــم علــى‬\n     ‫املع ــاملة الــواردة مــن فضيلــة رئيــس احملكمــة الع ــامة يف محافظــة‬\n     ‫عنيــزة برق ــم (‪ )33880351‬يف ‪1434/2/18‬هــ؛ املرفــق بهــا الصــك‬\n     ‫رقــم (‪ )33480601‬يف ‪1433/12/28‬هــ؛ الصــادر مــن فضيلــة الشــيخ‪/‬‬\n     ‫القاضــي يف احملكمــة؛ اخلــاص بدعــوى‪ /‬بالوكالــة عــن‪ /‬ضد‪ /‬؛ بشــأن‬\n     ‫حــادث مــروري وطلبــه إلــزام املدعــى عليــه تســليمه أرش تلفيــات ســيارة‬\n     ‫موكلتــه‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه بــرد دعــوى املدعــي‬\n     ‫املفصــل‬\n         ‫َّ‬     ‫وكالــة وأخلــى ســبيل املدعــى عليــه مــن الدعــوى؛ علــى النحــو‬\n     ‫فيــه‪ ،‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى مــا حكــم بــه فضيلتــه‪ .‬واهلل‬\n                  ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":61,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eacb3fa3821e2bb84bee228a37006d8e3c90af30ba3a4e31963075a112245a75","normalized_text_hash":"df4e796d68ff191cb39b73b444d824d80e8f1f993b7f580cda81caa288c8e8cb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p61-33480601"},{"id":"f958410f-fb1c-5a34-a6c4-ae0fec5844e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -اصطدام سيارتني -املطالبة بأرش تلفيات سيارة -ملكية السيارة جلهة حكومية -صرف النظر عن الدعوى ألن املدعى ليس بذي صفة تخول له إقامة الدعوى .","document_number":"34178783","case_number":"3493080","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/3","year":"1434","subject":"حادث مروري -اصطدام سيارتني -املطالبة بأرش تلفيات سيارة -ملكية السيارة جلهة حكومية -صرف النظر عن الدعوى ألن املدعى ليس بذي صفة تخول له إقامة الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34178783 :‬‬\n                    ‫َر ْق ُم الدعوى‪3493080 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34249233‬تاريخه‪1434/6/24 :‬هـ‬\n\n\n‫حــادث مــروري ‪ -‬اصطــدام ســيارتني ‪ -‬املطالبــة بــأرش تلفيــات ســيارة‬\n‫‪ -‬ملكيــة الســيارة جلهــة حكوميــة ‪ -‬صــرف النظــر عــن الدعــوى ألن‬\n                 ‫املدعــى ليــس بــذي صفــة تخــول لــه إقامــة الدعــوى ‪.‬‬\n\n\n\n\n        ‫املادة (‪ )1/30‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة علــى املدعــى عليــه بــأن ابــن موكلــه كان يقــود‬\n‫ســيارة يف عهــدة والــده املدعــي أصالــة وهــى مملوكــة لقــوات األمــن‬\n‫اخلاصــة التابعــة لــوزارة الداخليــة حيــث اعتــرض املدعــى عليــه بســيارته‬\n‫وذلــك بخروجــه مــن املنطقــة الترابيــة إلــى الطريــق العــام فارتطــم بــه ابــن‬\n‫املدعــي أصالــة ‪ -‬نتــج عــن احلــادث تلفيــات بالســيارة التــي يقودهــا ابــن‬\n‫املدعــي أصالــة قــدرت بســبعة عشــر ألــف ريــال ‪ -‬أديــن املدعــى عليــه‬\n‫بنســبة اخلطــأ كاملــة ‪ %100‬مبوجــب تقريــر املــرور ‪ -‬طلــب املدعــي‬\n‫وكالــة إلــزام املدعــى عليــه بدفــع قيمــة األرش للمدعــى أصالــة ألن‬\n‫الســيارة وإن كانــت مملوكــة للقــوات اخلاصــة إال أنهــا يف عهــدة املدعي‬\n‫اصالــة ‪ -‬صــادق املدعــى عليــه علــى مــا جــاء يف الدعــوى ‪ -‬دفــع املدعــى‬\n‫عليــه بأنــه غيــر مقتنــع بتقريــر املــرور ألن الطريــق كان بــه إشــارات‬\n\n                                                                                       ‫‪70‬‬\n\f     ‫تنبيــه بتهدئــة الســرعة إال أن ابــن املدعــي أصالــة كان يســير مســرع ًا‬\n     ‫‪ -‬جــرى االطــاع علــى أوراق املعاملــة وهــى مطابقــة ملــا ذكــره املدعــي‬\n     ‫وكالــة ‪ -‬حيــث قــرر املدعــي وكالــة بــأن الســيارة ال تعــود ملكيتهــا‬\n     ‫ملوكلــه وإمنــا تعــود ملكيتهــا للقــوات اخلاصــة بــوزارة الداخليــة وعليــه‬\n     ‫فاملدعــي أصالــة ليــس بــذي صفــة تخــول لــه إقامــة هــذه الدعــوى ‪ -‬لــذا‬\n     ‫صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــى وكالــة وجــرى إفهامــه‬\n     ‫بــأن ملرجــع موكلــه احلــق يف املطالبــة بالدعــوى متــى أرادت ذلــك بإرســال‬\n     ‫منــدوب ميثلهــا أو تفويــض موكلــه بذلــك ‪ -‬اعتــرض املدعــي وكالــة‬\n                   ‫علــى احلكــم ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا املــازم القضائــي ‪ ...‬مبكتــب فضيلــة‬\n     ‫القاضي الشيخ ‪ ...‬وبتكليف من فضيلته وبناء على املعاملة احملالة لنا‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكة املكرمــة برقم ‪3493080‬‬\n     ‫وتاريــخ ‪ 1434/02/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34477647‬وتاريخ‬\n     ‫‪ 1434/02/25‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/04/03‬هـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر ‪ ... /‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيــا عــن ‪ ...‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة ونــص احلاجــة‬\n     ‫منهــا (ولــه حــق املرافعــة وحضــور اجللســات وإقامــة الدعــاوى وســماع‬\n     ‫الشــهود والطعــن فيهــم واســتجوابهم والصلــح وطلــب حتليــف اليمــن‬\n     ‫وتوريــد الشــهود ‪..‬الــخ) فأدعــى علــى احلاضــر معــه يف مجلــس القضــاء ‪/‬‬\n     ‫ا يف دعــواه ضــده‬ ‫‪ ...‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬قائ ـ ً‬\n\n‫‪71‬‬\n\f‫‪ :‬إنــه بتاريــخ ‪1434/1/13‬ه ـ الســاعة التاســعة صباحــا حصــل بــن ابــن‬\n‫مــوكل ‪ ...‬تصــادم بينــه وبــن هــذا احلاضــر بســيارته نــوع ‪ ....‬العائــدة‬\n‫ملكيتهــا لقــوات األمــن اخلاصــة بطريــق مكــة الطائــف الســريع بعــد‬\n‫مفــرق الشــاحنات جتــاه مكــة حيــث اعتــرض املدعــى عليــه هــذا أمــام‬\n‫ابــن موكلــي بخروجــه مــن املنطقــة الترابيــة إلــى الطريــق متجــاوز اخلــط‬\n‫األميــن ثــم األوســط الــذي كان ميــر بــه ابــن موكلــي يريــد الذهــاب إلــى‬\n‫الطــرف اآلخــر مــع العلــم أن اخلــط األيســر مقفــل بســبب وجــود أعمــال بــه‬\n‫بســيارة نــوع ‪ ....‬فارتطــم ابــن موكلــي يف ســيارة املدعــى عليــه نتــج عــن‬\n‫احلــادث تلفيــات بســيارت موكلــي التــي يف عهدتــه قــدر أرشــها مببلــغ‬\n‫ســبعة عشــر ألــف ريــال وأديــن هــذا احلاضــر بكامــل مســؤولية احلــادث‬\n‫‪ %100‬أطلــب إلزامــه بدفــع كامــل هــذا املبلــغ ‪ .‬هكــذا أدعــى املدعــي‬\n‫ولــدى عــرض الدعــوى علــى املدعــى عليــه بواســطة املترجــم املتعــاون ‪...‬‬\n‫باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬أجــاب قائــا مــا ذكــره‬\n‫املدعــي يف دعــواه كلــه صحيــح غيــر أن يف الطريــق قبــل املنطقــة التــي‬\n‫فيهــا العمــل بأربعــة مائــة متــر إشــارات تنبــه بالتهدئــة الســرعة وهــو‬\n‫كان مســرعا ولذلــك أنــا غيــر مقتنــع بنســبة املســؤولية التــي ذكرهــا‬\n‫املــرور ‪.‬فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة واالطــاع علــى أوراق‬\n‫املعاملــة فوجدتهــا مطابقــة ملــا ذكــره املدعــي وكالــة وإلقــراره بــأن‬\n‫ملكيــة الســيارة ال تعــود إلــى موكلــه بــل تعــود للقــوات اخلاصــة بــوزارة‬\n‫الداخليــة فقــد صرفــت النظــر عــن دعــوى املدعــي وكالــة ألن ملكيــة‬\n‫الســيارة ال تعــود ملوكلــه وألن موكلــه ليــس لــه صفــة يف املطالبــة كمــا‬\n‫أشــارت املــادة ‪ 1/30‬مــن نظــام املرافعــات مــع الئحتــه وأفهمتــه بأن ملرجع‬\n‫موكلــه احلــق يف املطالبــة بالدعــوى متــى مــا أرادت ذلــك بإرســال مندوبـ ًا‬\n\n\n                                                                                    ‫‪72‬‬\n\f     ‫ميثلهــا أو بتفويــض موكلــك باملطالبــة عنهــا وبعــرض ذلــك علــى الطرفــن‬\n     ‫قــرر املدعــي عليــه القناعــة باحلكــم كمــا قــرر املدعــي وكالــة بعــدم‬\n     ‫القناعــة وطلــب االســتئناف وأســتعد بتقــدمي الالئحــة االعتراضيــة وأفهــم‬\n     ‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم نســخه مــن احلكــم‬\n     ‫وأفهــم بــأن لــه ثالثــن يومــا مــن تاريــخ اســتالمه لنســخة احلكــم لتقــدمي‬\n     ‫اعتراضــه علــى احلكــم فــإذا انتهــت املــدة ســقط حقــه يف االعتــراض‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1434/4/3‬ه ـ ‪.‬‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد‪:‬‬\n     ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n     ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n     ‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة‬\n     ‫رقــم(‪ )34792128‬وتاريــخ (‪1434/6/18‬هــ) املرفــق بهــا القــرار‬\n     ‫رقــم(‪ )34178783‬وتاريــخ (‪1434/4/3‬هـ)الصــادر مــن فضيلــة الشــيخ‪/‬‬\n     ‫‪ ...‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة ‪،‬املتضمــن دعــوى‪.../‬‬\n     ‫ســعودي اجلنســية ضــد‪ ... /‬باكســتاني اجلنســية ‪ ،‬يف حــادث مــروري‬\n     ‫احملكــوم فيــه مبــا دون باطنــه ‪ ، ،‬وبدراســة القــرار وصــورة ضبطــه‬\n     ‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‪،‬‬\n                   ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪73‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":70,"source_page_end":73,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cbc75113fe04ebbf4ff8264791ba0cb3b4a830647175ebd058dbd64e4255f8a4","normalized_text_hash":"a9060ecac79336e2ceb52555dd8698ecef5b9d27970841732dfcaff96b496557","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p70-34178783"},{"id":"6d95a8e1-9678-5579-ba3c-48c97a24e8a8","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -اصطدام سيارتني -االختاف يف تقدير األرش - إثبات اإلدانة بنسبة اخلطأ كاملة بسبب قطع اإلشارة -الدفع بأن سبب قطع اإلشارة بناء على توجيه املرور -طلب إعادة التحقيق يف احلادث -تقدير أهل اخلبرة -احلكم بالتقدير األقل لأرش ألنه","document_number":"34219920","case_number":"3418825","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/20","year":"1434","subject":"حادث مروري -اصطدام سيارتني -االختاف يف تقدير األرش - إثبات اإلدانة بنسبة اخلطأ كاملة بسبب قطع اإلشارة -الدفع بأن سبب قطع اإلشارة بناء على توجيه املرور -طلب إعادة التحقيق يف احلادث -تقدير أهل اخلبرة -احلكم بالتقدير األقل لأرش ألنه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34219920 :‬‬\n                    ‫َر ْق ُم الدعوى‪3418825 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34263758‬تاريخه‪1434/7/10 :‬هـ‬\n\n\n‫حــادث مــروري ‪ -‬اصطــدام ســيارتني ‪ -‬االختــاف يف تقديــر األرش ‪-‬‬\n‫إثبــات اإلدانــة بنســبة اخلطــأ كاملــة بســبب قطــع اإلشــارة ‪ -‬الدفــع بأن‬\n‫ســبب قطــع اإلشــارة بنــاء علــى توجيــه املــرور ‪ -‬طلــب إعــادة التحقيــق يف‬\n‫احلــادث ‪ -‬تقديــر أهــل اخلبــرة ‪ -‬احلكــم بالتقديــر األقــل لــأرش ألنــه‬\n                                                                        ‫املتيقــن ‪.‬‬\n\n\n\n\n                                                   ‫قاعدة ‪ :‬األقل هو املتيقن ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي يف مواجهــة املدعــى عليــه بأنــه أثنــاء إضــاءة اإلشــارة‬\n‫باللــون األخضــر حتــرك بســيارته اال أن املدعــى عليــه قطــع اإلشــارة‬\n‫وتســبب يف وقــوع احلــادث ‪ -‬أديــن املدعــى عليــه بنســبة اخلطــأ كاملــة‬\n‫‪ - %100‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارته‬\n‫‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ‪ -‬دفــع املدعــى عليــه بأنــه‬\n‫كان يقــود ســيارة لنقــل األمــوال وأن قائــد ســيارة الدوريــة املرافــق لــه‬\n‫أمــره بقطــع اإلشــارة بنــاء علــى أن التعليمــات التــي لديــه بــان ســيارات‬\n‫األمــوال ال تقــف عنــد اإلشــارات ‪ -‬طلــب القاضــي إعــادة التحقيــق يف‬\n‫احلــادث وأعيــدت املعاملــة للمــرور ‪ -‬عــادت املعاملــة مــن املــرور وتضمــن‬\n\n                                                                                      ‫‪74‬‬\n\f     ‫التقريــر بــأن رجــل األمــن قائــد الدوريــة ال يعتبــر طرفــا ثالثــا مــدان يف‬\n     ‫احلــادث وفقــا للمــادة (‪ )30/1/50‬مــن نظــام املــرور كمــا أن املركبــة‬\n     ‫قيــادة املدعــى عليــه ال تعتبــر مــن ســيارات الطــوارئ ‪ -‬جــرى الرجــوع‬\n     ‫إلــى تقريــر املــرور املتضمــن إدانــة املدعــى عليــه بنســبة اخلطــأ كاملــة‬\n     ‫‪ - %100‬جــرى الرجــوع إلــى تقديــر األرش ووجــد أنــه متفــاوت ‪ -‬جــرى‬\n     ‫األخــذ باألقــل ألنــه املتيقــن ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n     ‫أرش تلفيــات الســيارة للمدعــي (التقديــر األقــل) ‪ -‬جــرى إفهــام املدعــى‬\n     ‫عليــه بــأن لــه مطالبــة قائــد الدوريــة األمنيــة أو اجلهــة التابــع لهــا مبــا دفــع‬\n     ‫بــه ‪ -‬قنــع املدعــي ولــم يقنــع املدعــى عليــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                              ‫االســتئناف ‪.‬‬\n\n\n\n\n     ‫اجلزائية بســكاكا‬\n                     ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيس احملكمة‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنا برقــم ‪ 3418825‬وتاريخ ‪1434/01/12‬هـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3442212‬وتاريــخ ‪1434/01/06‬ه ـ ففــي يوم‬\n     ‫الثالثــاء املوافق‪1434/02/26‬ه ـ افتتحــت اجللســة األولى يف متام الســاعة‬\n     ‫‪ 09 : 00‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ...‬وادعــى علــى احلاضــر معــه ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا‬\n     ‫يف دعــواه لقــد كنــت أســير يف ســيارتي وهــي نــوع ‪ .....‬صنــع ‪2002‬م علــى‬\n     ‫طريــق األميــر فهــد بــن بــدر قادمــا مــن الشــرق باجتــاه الغــرب فأضــاءت‬\n     ‫لــي اإلشــارة باللــون األخضــر وحتركــت إال أن هــذا احلاضــر قــام بقطــع‬\n     ‫اإلشــارة وتســبب يف وقــوع احلــادث وقــد أديــن بنســبة ‪ %100‬مــن مســؤولية‬\n     ‫احلــادث وقــدرت ســيارتي مــن قبــل أهــل اخلبــرة بســتة آالف ريــال أطلــب‬\n\n‫‪75‬‬\n\f‫احلكــم علــى هــذا احلاضــر بدفــع هــذا املبلــغ لــي هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي كلــه صحيــح فقــد كنــت‬\n‫أقــود ســيارة ‪ ...‬اخلاصــة باألمــوال لتغذيــة الصرافــات وترافقنــا دوريــة‬\n‫أمنيــة وهــي التــي أمرتنــا بقطــع اإلشــارة بنــاء علــى توجيــه الدوريــة حيــث‬\n‫أفادنــي رجــل األمــن بــأن لديهــم تعليمــات بــأن ســيارات األمــوال ال تقــف‬\n‫عنــد اإلشــارات فلمــا توقفــت عند اإلشــارة قامت الدوريــة وأمرتني بقطع‬\n‫اإلشــارة فلمــا قطعــت اإلشــارة حصــل احلــادث هكــذا أجــاب لــذا قــررت‬\n‫إعــادة كامــل أوراق املعاملــة إلــى املــرور للتحقيــق يف احلــادث مــن جديــد‬\n‫وهــل مــا ذكــره املدعــى عليــه جتــاه رجــل األمــن يوجــد عليــه نــص نظامي‬\n‫وإلــى حــن ورود املعاملــة يتــم مواصلــة النظــر فيهــا وعليــه جــرى التوقيــع‬\n‫وأقفلــت اجللســة يف متــام الســاعة التاســعة والنصــف وبــاهلل التوفيــق ويف‬\n‫هــذا اليــوم األحــد املوافق‪1434/04/21‬ه ـ افتتحــت اجللســة الثانيــة يف‬\n‫متــام الســاعة ‪ 10:00‬وفيهــا حضــر املدعــي واملدعــى عليــه هــذا وقد وردت‬\n‫إلينــا املعاملــة وبرفقهــا خطــاب مديــر إدارة مــرور منطقــة اجلــوف بعــد أن‬\n‫مت رفعهــا مــن قبلنــا لعــرض أوراق املعاملــة علــى جلنــة احلــوادث وهــل رجــل‬\n‫األمــن املرافــق لســيارة ‪ ...‬طــرف ثالــث مــدان يف احلــادث فأفــاد أنــه مت‬\n‫عــرض األوراق علــى جلنــة احلــوادث ودونــت محضرهــا رقــم ‪ .....‬يف ‪..........‬‬\n‫واملتضمــن أن رجــل األمــن قائــد الدوريــة ال يعتبــر طرفــا ثالثــا مــدان يف‬\n‫احلــادث وفقــا للمــادة رقــم (‪ )30/1/50‬املتضمنــة (يف جميــع األحــوال‬\n‫ال تعفــي تعليمــات رجــل املــرور وال قواعــد املــرور وعالماتــه وإشــاراته‬\n‫الســائقني مــن واجباتهــم يف العنايــة والتــزام احلــرص واحلــذر) كمــا أن‬\n‫املــادة الرابعــة واخلمســن تتضمــن (أفضليــة املــرور ملركبــات الطــوارئ‬\n‫أثنــاء مباشــرة مهماتهــا واملواكــب الرســمية وال يعفــى ســائقوها مــن‬\n\n\n                                                                                      ‫‪76‬‬\n\f     ‫القيــادة مبــا يضمــن ســامة الغيــر) وهــذه املركبــة ال تعتبــر مــن ســيارات‬\n     ‫الطــوارئ انتهــى خطــاب مديــر إدارة منطقــة اجلــوف والــذي يحمــل رقــم‬\n     ‫‪ .............‬يف ‪1434/03/10‬ه ـ كمــا وجــدت قــرار جلنــة احلــوادث رقــم ‪.....‬‬\n     ‫يف ‪1434/03/10‬ه ـ املــدون علــى اللفــة إحــدى وعشــرين ويتضمــن هــذا‬\n     ‫القــرار بعــد املقدمــة إدانــة الطــرف األول ‪ ...‬بنســبة مئــة يف املئــة (‪)%100‬‬\n     ‫وذلــك لألســباب اآلتيــة ‪-1‬قطــع اإلشــارة وهــي حمــراء واعترافــه بذلــك‪.‬‬\n     ‫‪-2‬الفعــل موجــب للمســؤولية لعــدم مراعــات األنظمــة معرضــا نفســه‬\n     ‫واآلخريــن للخطــر‪ -3 .‬الســيارة التــي يقودهــا ال تعتبــر مــن ســيارات‬\n     ‫الطــوارئ التــي لهــا أفضليــة املــرور أثنــاء مباشــرة مهامهــا‪ .‬انتهــى‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــى عليــه قــال إن قائــد الدوريــة املرافقــة هــو‬\n     ‫الــذي أجبرنــا علــى قطــع اإلشــارة ويدعــى ‪ ...‬وأطلــب حضــوره هكــذا‬\n     ‫أفــاد لــذا جــرى رفــع اجللســة إلحضــار قائــد الدوريــة املرافقــة لســيارة‬\n     ‫املجــال وذلــك يــوم الثالثــاء القــادم ‪1434/04/23‬ه ـ الســاعة العاشــرة‬\n     ‫والربــع وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة العاشــرة‬\n     ‫والنصــف وبــاهلل التوفيــق‪ ،‬ويف هــذا اليــوم األحــد املوافــق‪1434/05/19‬‬\n     ‫ه ـ افتتحــت اجللســة اخلامســة الســاعة الثانيــة عشــرة وفيهــا حضــر‬\n     ‫الطرفــان ولــم يحضــر رجــل األمــن هــذا وقــد جــرى االطــاع علــى‬\n     ‫أوراق املعاملــة فوجــدت مــن بــن طياتهــا تقديــرات أهــل اخلبــرة لســيارة‬\n     ‫املدعــي املدونــة علــى اللفــة األولــى والثانيــة والثالثــة وباالطــاع عليهــا‬\n     ‫وجدتهــا مختلفــة وأقــل هــذه التقديــرات هــو خمســة آالف ريــال لــذا وبنــاء‬\n     ‫علــى ماســبق مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى‬\n     ‫دعــوى املدعــي ودفــع بــأن الــذي أمــره بقطــع اإلشــارة هــو رجــل االمــن‬\n     ‫قائــد الدوريــة املرافقــة لســيارة املجــال وحيــث مت إعــادة املعاملــة إلــى‬\n\n\n‫‪77‬‬\n\f‫مــرور منطقــة اجلــوف هــل رجــل االمــن يكــون طرفــا يف القضيــة وحيــث‬\n‫جــاء يف قــرار اللجنــة وخطــاب مديــر املــرور بــأن رجــل األمــن اليكــون‬\n‫طرفــا يف ذلــك وحيــث إن الســيارة التــي يقودهــا املدعــى عليــه التعتبــر‬\n‫مــن ســيارات الطــوارىء وملاجــاء يف خطــاب مديــر املــرور وقــرار اللجنــة‬\n‫املشــار إليهمــا ســابقا وحيــث اختلفــت تقديــرات أهــل اخلبــرة لســيارة‬\n‫املدعــي وحيــث إن أقــل هــذه التقديــرات هــو خمســة آالف ريــال وحيــث‬\n‫إن األقــل هــو املتيقــن لــذا فقــد ألزمــت املدعــى عليــه بدفــع خمســة آالف‬\n‫ريــال للمدعــي قيمــة أرش نقــص ســيارته وبذلــك قضيــت وأفهمــت‬\n‫املدعــى عليــه إن كان لــه مطالبــة ضــد قائــد الدوريــة األمنيــة أو اجلهــة‬\n‫التابــع لهــا رجــل األمــن فلــه إقامتهــا مــع مراعــاة االختصــاص النوعــي‬\n‫يف هــذه القضيــة وبعــرض ذلــك علــى الطرفــن قــرر املدعــي القناعــة‬\n‫أمــا املدعــى عليــه فقــرر عــدم القناعــة وطلــب االســتئناف فأفهمتــه أن‬\n‫عليــه مراجعــة احملكمــة يــوم األربعــاء القــادم املوافــق ‪1434/5/22‬ه ـ‬\n‫الســاعة احلاديــة عشــرة الســتالم نســخة مــن احلكــم وأن لــه مــدة نظاميــة‬\n‫مــن ذلــك التاريــخ وهــي ثالثــون يومــا يقــدم خاللهــا الئحتــه االعتراضيــة‬\n‫ففهــم ذلــك وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة الثانيــة‬\n‫عشــرة والربــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بســكاكا‬\n‫الشــيخ‪ ... /‬برقــم ‪ 34635341‬وتاريــخ ‪1434/6/20‬ه ـ املرفــق بها الصك‬\n‫الصــادر مــن فضيلتــه املســجل برقــم ‪ ...‬وتاريــخ ‪1434/5/22‬ه ـ اخلــاص‬\n\n\n                                                                                      ‫‪78‬‬\n\f     ‫بدعــوى املدعــي ‪ ... /‬ضــد ‪ ... /‬يف قضيــة حــادث وقــد تضمــن الصــك‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة األعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n     ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                          ‫وســلم ‪.‬‬\n\n\n\n\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":74,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c6e53fa8980444a95a27758189fe972df121fc93f2b5e761e5a4747076d550bb","normalized_text_hash":"d972c7ba74612fee5a216d55d4cc82d1911155023c398cf11b1c6cf22c935851","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p74-34219920"},{"id":"6083d65e-313a-5a82-a878-64649921016b","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -اصطدام سيارتني -إثبات اإلدانة مبوجب تقرير املرور -تقدير قيمة تلفيات السيارة -كفالة غرم وأداء لسائق السيارة -املطالبة بدفع قيمة تلفيات السيارة -االختاف يف تقدير األرش -األخذ باألقل يف تقدير املتقومات ألنه املتفق عليه وهو املتيقن -اإللزام بدفع قيمة تلفيات السيارة بعد احلادث .","document_number":"34278439","case_number":"3471574","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بسكاكا وبن لنا من إدارة مرور منطقة اجلوف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/24","year":"1434","subject":"حادث مروري -اصطدام سيارتني -إثبات اإلدانة مبوجب تقرير املرور -تقدير قيمة تلفيات السيارة -كفالة غرم وأداء لسائق السيارة -املطالبة بدفع قيمة تلفيات السيارة -االختاف يف تقدير األرش -األخذ باألقل يف تقدير املتقومات ألنه املتفق عليه وهو املتيقن -اإللزام بدفع قيمة تلفيات السيارة بعد احلادث .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/24 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34278439 :‬‬\n                    ‫َر ْق ُم الدعوى‪3471574 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪ 34345308‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n‫حــادث مــروري ‪ -‬اصطــدام ســيارتني ‪ -‬إثبــات اإلدانــة مبوجــب تقريــر‬\n‫املــرور‪ -‬تقديــر قيمــة تلفيــات الســيارة ‪ -‬كفالــة غــرم وأداء لســائق‬\n‫الســيارة ‪ -‬املطالبــة بدفــع قيمــة تلفيــات الســيارة ‪ -‬االختــاف يف‬\n‫تقديــر األرش ‪ -‬األخــذ باألقــل يف تقديــر املتقومــات ألنــه املتفــق عليــه‬\n‫وهــو املتيقــن ‪ -‬اإللــزام بدفــع قيمــة تلفيــات الســيارة بعــد احلــادث ‪.‬‬\n\n\n\n\n       ‫األخذ باألقل يف تقدير املتقومات ألنه املتفق عليه وهو املتيقن ‪.‬‬\n       ‫انظر كشاف القناع (‪ ، )246/15‬وشرح منتهى اإلرادات (‪)534/3‬‬\n\n\n\n\n‫ادعــى وكيــل املدعيــة علــى املدعــى عليــه بــأن ســيارة موكلتــه تعرضــت‬\n‫للصــدم وجهــا لوجــه مــن قبــل ســيارة قيــادة عامــل حتــت كفالــة املدعــى‬\n‫عليــه ‪ -‬نتــج عــن احلــادث تلفيــات بســيارة املدعيــة ‪ -‬أديــن العامل مكفول‬\n‫املدعــى عليــه بنســبة اخلطــأ كاملــة ‪ %100‬حســب تقريــر املــرور ‪ -‬كفــل‬\n‫املدعــى عليــه الســائق املــدان كفالــة غــرم وأداء ‪ -‬طلــب املدعــي وكالــة‬\n‫إلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارة موكلتــه ‪ -‬اقــر املدعــى‬\n‫عليــه مبــا جــاء يف الدعــوى ‪ -‬توجــد ثالثــة تقاريــر مختلفــة ألرش تلفيــات‬\n‫ســيارة املدعيــة أصالــة ‪ -‬جــرى الرجــوع إلــى تقريــر املــرور املتضمــن إدانــة‬\n\n                                                                                      ‫‪80‬‬\n\f     ‫الســائق مكفــول املدعــى عليــه بنســبة اخلطــأ كاملــة ‪ - %100‬ملــا ذكره‬\n     ‫أهــل العلــم مــن انــه عنــد تقديــر املتقومــات يلــزم األقــل ألنــه املتيقــن وهــو‬\n     ‫املتفــق عليــه لــذا صــدر احلكــم بإلــزام املدعــى عليــه بدفــع األرش األقــل‬\n     ‫للمدعيــة أصالــة ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم‬\n                                                            ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمد هلل وحده ‪ ،‬والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد‪ :‬فلدي‬\n     ‫ـاء على املعاملة الواردة‬ ‫أنــا ‪ ...‬القاضــي باحملكمــة العامة بســكاكا وبنـ ً‬\n     ‫لنــا مــن إدارة مــرور منطقــة اجلوف برقم ‪4/73/11/7‬ح يف ‪1434/1/10‬‬\n     ‫هـ واملقيدة لدى احملكمة برقم ‪ 3490608‬يف ‪ 1434/1/12‬هـ واحملالة‬\n     ‫إلينــا مــن فضيلــة الرئيــس فإنــه يف يــوم االثنــن املوافــق ‪1434/7/24‬‬\n     ‫ه ـ فتحــت اجللســة وفيهــا حضــر‪ ... /‬ســعودي اجلنســية مبوجــب الهويــة‬\n     ‫الوطنيــة رقــم ‪ ...‬الوكيــل عــن زوجتــه‪ ... /‬مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل الدلــم برقــم ‪ 2894‬يف ‪ 1429/7/4‬ه ـ فادعــى ضــد‬\n     ‫احلاضــر معــه يف مجلــس احلكــم‪ ... /‬ســعودي اجلنســية مبوجــب الهويــة‬\n     ‫ا يف دعــواه ضــده‪ :‬إنــه بتاريــخ ‪ 1433/12/20‬ه ـ‬          ‫الوطنيــة رقــم ‪ ...‬قائ ـ ً‬\n     ‫وقــع حــادث مــروري يف بســيطا مبحافظــة طبرجــل لســيارة موكلتــي مــن‬\n     ‫نــوع مرســيدس تريــا موديــل (‪ )....‬رقــم اللوحــة (‪ )......‬حيــث أن الســائق‪/‬‬\n     ‫‪ ...‬مصــري اجلنســية الــذي يعمــل لــدى موكلتــي وكان يقــود الســيارة‬\n     ‫املذكــورة فاصطدمــت بــه ســيارة مــن نــوع ايســوزو دينــا موديــل (‪ )....‬رقم‬\n     ‫اللوحــة (‪ )......‬بقيــادة‪ ... /‬هنــدي اجلنســية وجهـ ًا لوجــه وحــدث تلفيــات يف‬\n     ‫مقدمــة ســيارة موكلتــي املذكــورة ‪ ،‬وقــد أديــن قائــد الســيارة الدينــا‬\n\n‫‪81‬‬\n\f‫املذكــورة باحلــادث بنســبة (‪ )%100‬وقــدرت قيمــة ســيارة موكلتــي قبــل‬\n‫وبعــد احلــادث والفــرق مبلــغ وقــدره ســتة وثمانــون ألــف ريــال (‪)86000‬‬\n‫‪ ،‬ومبــا أن املدعــى عليــه قــد كفــل قائــد الســيارة الدينــا املذكــورة‬\n‫كفالــة غــرم وأداء ‪ ،‬لــذا أطلــب إلــزام املدعــى عليــه بدفــع قيمــة نقــص‬\n‫قيمــة ســيارة موكلتــي بعــد احلــادث وقدرهــا ســتة ثمانــون ألــف ريــال‬\n‫(‪ ، )86000‬هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه ضــدي فكلــه صحيــح‬\n‫ا ‪ ،‬وليــس لــدي أي اعتــراض ‪ ،‬هــذه إجابتــي ‪ .‬وباإلطــاع‬     ‫جملــة وتفصيـ ً‬\n‫علــى أوراق املعاملــة وجــدت فيهــا ملخــص للحــادث واملتضمــن‪ :‬إدانــة‬\n‫قائــد الســيارة الدينــا املدعــو‪ ... /‬هنــدي اجلنســية بنســبة (‪)%100‬‬\n‫جتــاه احلــادث ؛ لدخولــه يف مســار الســيارة األخــرى وعــدم االنتبــاه ‪،‬‬\n‫كمــا وجــدت يف املعاملــة ثــاث تقاديــر لقيمــة ســيارة موكلــة املدعــي‬\n‫قبــل وبعــد احلــادث األولــى صــادرة مــن معــرض ‪ ...‬واملتضمنــة أن أرش‬\n‫النقــص مائــة وألفــا ريــال (‪ ، )102000‬والثانيــة صــادرة مــن معــرض‬\n‫‪ ...‬واملتضمنــة أن أرش النقــص ثمانــون ألــف ريــال (‪ ، )80000‬والثالثــة‬\n‫صــادرة مــن معــرض ‪ ...‬واملتضمنــة أن أرش النقــص واحــد وثمانــون ألــف‬\n‫ريــال (‪ . )81000‬فبعــد ســماع الدعــوى واإلجابــة واإلطــاع علــى أوراق‬\n‫املعاملــة ‪ ،‬ومبــا أن املدعــي وكالــة ذكــر بــأن ســيارة موكلتــه تعرضــت‬\n‫حلــادث مــن قبــل ســيارة مكفــول املدعــى عليــه وحصــل لهــا تلفيــات يف‬\n‫املقدمــة ‪ ،‬ومبــا أن املدعــى عليــه صــادق علــى مــا جــاء يف دعــوى املدعــي‬\n‫‪ ،‬ومبــا أن مكفــول املدعــى عليــه أديــن مبســؤوليته عــن احلــادث بنســبة‬\n‫(‪ )%100‬ولــم يعتــرض علــى ذلــك ‪ ،‬ومبــا أن املتفــق عليــه يف التســعيرات‬\n‫ـاء علــى مــا ذكــره أهــل العلــم يف اإلختــاف‬\n                                               ‫هــو ثمانــون ألــف ريــال ‪ ،‬وبنـ ً‬\n\n                                                                                     ‫‪82‬‬\n\f     ‫يف تقــومي املتقومــات أنــه يلزمــه مــا اتفــق عليــه وأنــه هــو اليقــن ‪ ،‬ينظــر يف‬\n     ‫ذلــك كشــاف القنــاع ‪ 246/15‬وشــرح منتهــى اإلرادات ‪ ، 534/3‬لــذا‬\n     ‫فقــد حكمــت بإلــزام املدعــى عليــه‪ ... /‬أن يدفــع للمدعيــة أصالــة‪... /‬‬\n     ‫أرش نقــص قيمــة ســيارتها املذكــورة يف الدعــوى بعــد احلــادث وقدرهــا‬\n     ‫ثمانــون ألــف ريــال (‪ )80000‬حــا ًال ‪ ،‬وأفهمــت املدعــى عليــه أن لــه حــق‬\n     ‫الرجــوع علــى مكفولــه بهــذا املبلــغ ‪ .‬وبعــرض احلكــم علــى الطرفــن‬\n     ‫قــرر املدعــي وكالــة القناعــة وأمــا املدعــى عليــه فقــرر عــدم القناعــة‬\n     ‫‪ .‬فأفهمتــه مبراجعــة احملكمــة يــوم غــدٍ الثالثــاء الســتالم نســخة مــن‬\n     ‫احلكــم ليقــدم اعتراضــه عليــه خــال مــدة االعتــراض وهــي ثالثــون‬\n     ‫يوم ـ ًا مــن تاريــخ االســتالم ‪ ،‬وأنــه إذا لــم يحضــر فســوف يــودع الصــك‬\n     ‫يف ملــف الدعــوى ويكــون إيداعــه مجريـ ًا ملــدة االعتــراض ‪ ،‬وإذا انتهــت‬\n     ‫املــدة ولــم يقــدم اعتراضــه ســقط حقــه يف طلــب التمييــز واكتســب‬\n     ‫احلكــم القطعيــة ‪ ،‬فأبــدى فهمــه لذلــك‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪ 1434/7/24‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ففــي هــذا اليــوم األحــد املوافــق ‪1434/12/1‬‬\n     ‫ه ـ وردتنــا املعاملــة مــن محكمــة االســتئناف باجلــوف مرفقـ ًا بهــا القــرار‬\n     ‫رقــم ‪ 34345308‬يف ‪ 1434/10/29‬ه ـ واملتضمــن مــا نصــه‪( :‬وبدراســة‬\n     ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة فقــد‬\n     ‫قررنــا املصادقــة علــى احلكــم) واملظهــر بــه علــى صــك احلكــم‪ ،‬بتوقيــع‬\n     ‫وختــم أصحــاب الفضيلــة قضــاة الدائــرة األولــى لتمييــز القضايــا‬\n     ‫اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف‪ ،‬وللمعلوميــة جــرى‬\n     ‫إثباتــه‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف‬\n                                                                      ‫‪ 1434/12/1‬ه ـ ‪.‬‬\n\n\n‫‪83‬‬\n\f‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بســكاكا برقــم‬\n‫‪ 3490608‬وتاريــخ ‪1434/9/2‬ه ـ املرفــق بهــا الصــك الصــادر من فضيلة‬\n‫القاضي باحملكمة الشيخ ‪ ... /‬املسجل برقم ‪ ...‬وتاريخ ‪1434/7/24‬هـ‬\n‫اخلــاص بدعــوى املدعــي‪ ... /‬وكيــل عــن ‪ ...‬ضــد‪ ... /‬يف قضيــة حــادث‬\n‫مــروري وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫فقــد قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪84‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":80,"source_page_end":84,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fbbe33483ecf7c024fac12845f78480c980a94ef46eb1c368f6825555dae0b46","normalized_text_hash":"c22308e388e6f344e091af4ba94aa84a7302e001f0c5de1e4c329968a02441a1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p80-34278439"},{"id":"a5472334-b252-5658-9090-e77d1b493dca","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -قطع إشارة وتصادم سيارتني -مطالبة بقيمة تلفيات السيارة -إدانة املدعى عليه بكامل املسئولية -حلف املدعي اليمن- إلزام املدعى عليه بدفع قيمة تلفيات سيارة املدعي .","document_number":"34338542","case_number":"34128953","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/22","year":"1434","subject":"حادث مروري -قطع إشارة وتصادم سيارتني -مطالبة بقيمة تلفيات السيارة -إدانة املدعى عليه بكامل املسئولية -حلف املدعي اليمن- إلزام املدعى عليه بدفع قيمة تلفيات سيارة املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/10/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34338542 :‬‬\n                         ‫َر ْق ُم الدعوى‪34128953 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34364390‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n      ‫حــادث مــروري‪ -‬قطــع إشــارة وتصــادم ســيارتني‪ -‬مطالبــة بقيمــة تلفيــات‬\n      ‫الســيارة‪ -‬إدانــة املدعــى عليــه بكامــل املســئولية‪ -‬حلــف املدعــي اليمــن‪-‬‬\n                       ‫إلــزام املدعــى عليــه بدفــع قيمــة تلفيــات ســيارة املدعــي ‪.‬‬\n\n\n\n\n            ‫‪ -1‬ما قرره العلماء من اليمن تشرع يف جانب أقوى املتداعيني ‪.‬‬\n      ‫‪ -2‬فتــوى ســماحة الشــيخ محمــد بــن إبراهيــم (واذا لــم تثبــت الدعــوى‬\n      ‫ببينــة وال إقــرار ووجــدت القرائــن القويــة الدالــة علــى صــدق الدعــوى‬\n      ‫تقــوى بيمــن املدعــى) تعميــم صــادر مــن ســماحته برقــم ‪ 17‬يف‬\n                    ‫‪1380/1/18‬ه ـ مــن كتــاب األنظمــة واللوائــح صـ ــ‪.128‬‬\n\n\n\n\n      ‫دعــوى املدعــي ضــد املدعــى عليــه بأنــه حصــل حــادث مــروري بــن‬\n      ‫املدعــي واملدعــى عليــه حيــث إن املدعــي كان متوقفــا عنــد اإلشــارة‬\n      ‫وهــى حمــراء فلمــا صــارت خضــراء حتــرك املدعــي وقــدم املدعــى‬\n      ‫عليــه مــن اليســار قاطعــا اإلشــارة ممــا أدى إلــى اصطدامــه باملدعــى‬\n      ‫وإدانتــه بنســبة اخلطــأ ‪ %100‬وقــدرت التلفيــات بســيارة املدعــى مبلغــا‬\n      ‫قــدرة واحــد وثالثــون ألــف ريــال وطلــب إلــزام املدعــى عليــه بتســليم هــذا‬\n      ‫املبلــغ ‪ -‬صــادق املدعــى عليــه علــى احلــادث وانكــر قطــع اإلشــارة وقــرر‬\n\n‫‪85‬‬\n\f‫أن املدعــي هــو الــذي قطــع اإلشــارة ‪ -‬طلــب ناظــر القضيــة مــن املدعــي‬\n‫البينــة علــى أن املدعــي عليــه قطــع اإلشــارة فقــرر أن بينتــه تقريــر احلــادث‬\n‫‪ -‬اطلــع حاكــم القضيــة علــى تقريــر املــرور فوجــده كمــا ذكــر املدعــي‬\n‫ومشــار فيــه إلــى أن الــذي قطــع اإلشــارة هــو املدعــى عليــه بنــاء علــى‬\n‫شــهادة شــاهد مدونــة يف تقريــر املــرور ‪ -‬بنــاء علــى مــا ظهــر حلاكــم‬\n‫القضيــة وأن املدعــى هــو أقــوى جانــب مــن املدعــى عليــه فقــد طلــب منــه‬\n‫أداء اليمــن وحلــف علــى صحــة دعــواه ‪ -‬وصــدر احلكــم بإلــزام املدعــى‬\n‫عليــه بتســليم املدعــي قيمــة تلفيــات الســيارة حســب املبلــغ املدعــى بــه ‪-‬‬\n‫قــرر املدعــى عليــه عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف‬\n                                ‫مبكــة املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبــع‪ /‬املســاعد برقــم ‪ 34128953‬وتاريــخ ‪ 1434/03/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34588310‬وتاريــخ ‪ 1434/03/08‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/04/02‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 00‬‬\n‫وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ولــم‬\n‫يحضــر املدعــى عليــه ولــم يردنــا مــا يفيــد تبلغــه ورفعــت اجللســة إلعــادة‬\n‫تبليغ املدعى عليه‪ ،‬ففي يوم الســبت املوافق‪ 1434/05/04‬هـ افتتحت‬\n‫اجللســة الســاعة وفيهــا حضــر لدنيــا املدعــي وحضــر بحضــوره املدعــى‬\n‫عليــه نيبالــي اجلنســية مبوجــب جــواز ســفر رقــم وبعــد حضورهمــا أدعــى‬\n‫املدعــي بقولــه لقــد حصــل حــادث تصــادم بينــي وبــن املدعــى عليــه حيــث‬\n\n                                                                                       ‫‪86‬‬\n\f     ‫كنــت متوقــف عنــد إشــارة تقاطــع طريــق البحــر مع طريق جــدة وتوقفت‬\n     ‫عنــد اإلشــارة وملــا أضــاءت اإلشــارة باللــون األخضــر حتركــت ثــم قــدم‬\n     ‫املدعــى عليــه بســيارته اخلالطــة مــن اليســار وكان قاطــع اإلشــارة حيــث‬\n     ‫أشــارته حمــراء ومــا أدى إلــى و قــوع احلــادث وقــد أديــن املدعــى عليــه‬\n     ‫بكامــل املســئولية عــن احلــادث بنســبة مئــة باملئــة ‪ %100‬وقــد قــدرت‬\n     ‫تلفيــات الســيارة مببلــغ واحــد وثالثــن ألــف ريــا ًال حســب تقييــم شــيخ‬\n     ‫املعــارض أطلــب إلــزام املدعــى عليــه بســدادها وبســؤال املدعــى عليــه‬\n     ‫بواســطة املترجــم باكســتاني اجلنســية مبوجــب رخصة إقامــة رقم أجاب‬\n     ‫بقولــه مــا ذكــره املدعــي مــن حصــول احلــادث فهــذا صحيــح ولكــن لــم‬\n     ‫أقطــع اإلشــارة حيــث كانــت اإلشــارة حــن مشــيت خضــراء وكانــت‬\n     ‫إشــارة املدعــي حمــراء واملدعــي هــو مــن قطــع اإلشــارة وأنــا غيــر مقتنــع‬\n     ‫بالنســبة حيــث إن املدعــي هــو مــن قطــع اإلشــارة هكــذا أجــاب وبعــرض‬\n     ‫ذلــك علــى املدعــي قــال بــل الصحيــح مــا ذكرتــه يف الدعــوى و التقريــر‬\n     ‫املــروري يفيــد ذلــك و بعــرض ذلــك علــى املدعــى عليــه قــال إن لــدي بينــه‬\n     ‫علــى أن املدعــي هــو مــن قطــع اإلشــارة وأنــي أطلــب مهلــه إلحضارهــا‬\n     ‫ورفعــت اجللســة لذلــك‪ ،‬ففــي يــوم اخلميــس املوافــق ‪ 1434/09/03‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 10:30‬صباح ـ ًا وفيهــا حضــر لدينــا املدعــي‬\n     ‫بالســجل املدنــي ولــم يحضــر املدعــى عليــه رغــم تبلغــه ملوعــد اجللســة‬\n     ‫حســب إقــراره املرفــق وبعــد حضــور املدعــي قــررت االســتمرار يف نظــر‬\n     ‫القضيــة فطلبــت مــن املدعــي البينــة علــى دعــواه فقــال إن بينتــي ماجــاء‬\n     ‫يف تقريــر املــرور املرفــق باملعاملــة فجــرى االطــاع علــى التقريــر الصــادر‬\n     ‫مــن شــعبه مــرور محافظــه ينبــع برقــم ‪ 3/1076/7/7‬يف ‪1434/3/7‬ه ـ‬\n     ‫ونــص احلاجــة منــه تقــع مســؤولية احلــادث بعينــه مائــه باملائــة علــى اخلالطه‬\n\n\n‫‪87‬‬\n\f‫بقيــاده وذلــك لالعتبــارات املدونــة علــى صفحــه ‪ 2‬مــن ملــف التحقيــق‬\n                             ‫‪01‬ه ـ فطلبــت منــه زيــادة بينــه ورفعــت اجللســة ‪.‬‬\n‫ففــي يــوم األربعــاء املوافــق‪ 1434/10/21‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10:15‬صباح ـ ًا وفيهــا حضــر لدينــا املدعــي واملدعــى عليــه و مترجــم‬\n‫احملكمــة باكســتاني اجلنســية مبوجــب رخصــة إقامــة رقــم () وبعــد‬\n‫حضورهــم جــرى ســؤال املدعــى عليــه عــن البينــة التــي وعــد بإحضارهــا‬\n‫علــى أن املدعــي هــو مــن قطــع اإلشــارة فأجــاب بقولــه ليــس لــي بينــه‬\n‫هكــذا أجــاب ثــم جــرى ســؤال املدعــي لديــك بينــه قــال أن بينتــي مــا‬\n‫جــاء يف صحيفــة (‪ )2‬مــن ملــف التحقيــق وهــي أســباب احلــادث ثــم جــرى‬\n‫االطــاع علــى ملــف التحقيــق املرفــق باملعاملــة صفحــة (‪ )2‬ونصــه تقــع‬\n‫مســؤولية احلــادث علــى قائــد اخلالطــة لألســباب التاليــة‪ -1 :‬جتــاوز‬\n‫اإلشــارة أثنــاء اللــون األحمــر حســب شــهادة الشــاهد ‪ -2‬عــدم حمــل‬\n‫رخصــة قيــادة تؤهلــه ممــا يــدل علــى جهــل األنظمــة ‪ -3‬عــدم اليقظــة و‬\n‫االنتبــاه خصوص ـ ًا أنــه ميــر بتقاطــع ‪ -4‬الســرعة الزائــدة ممــا يــدل علــى‬\n‫جســامة احلادث و انقالب الشــاحنة ‪ -5 .‬ما جاء يف الرســم الكروكي‬\n‫وكذلــك شــهادة املدونــة علــى صحيفــة رقــم (‪ )7‬مــن ملــف التحقيــق‬\n‫ونصهــا (أقــر أنــا ســعودي اجلنســية بالســجل املدنــي رقــم أقــر بأنــي‬\n‫كنــت متوقــف أمــام إشــارة تقاطــع البحــر مــع طــرق امللــك عبدالعزيــز‬\n‫وكانــت اإلشــارة حمــراء وبعــد مــا أضــاءت اإلشــارة باللــون األخضــر و‬\n‫أردت التحــرك شــاهدت الكــورال تأتــي مــن اليمــن و اإلشــارة خضــراء‬\n‫لنــا و أنــا توقفــت و لــم أشــهاد الشــاحنة إال عنــد وقــوع احلــادث هنــا نــص‬\n‫احلاجــة منهــا) وحيــث أن مــا قدمــه املدعــي مــن بينــات تقــوي جانبــه‬\n‫وحيــث أن اليمــن تشــرع يف جانــب أقــوى املتداعــن لذلــك كلــه فقــد‬\n\n\n                                                                                      ‫‪88‬‬\n\f     ‫طلبــت مــن املدعــي اليمــن بعــد أن خوفتــه بــاهلل فحلــف بــاهلل بقولــه‬\n     ‫أقســم بــاهلل العظيــم أن اإلشــارة كانــت خضــراء أثنــاء جتــاوزي لهــا وأن‬\n     ‫املدعــى عليــه هــو مــن قطــع اإلشــارة و تســبب باحلــادث هكــذا حلــف‪،‬‬\n     ‫ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة وعلــى تقريــر احلــادث‬\n     ‫الصــادر مــن مــرور محافــظ ينبــع املذكــور أعــاه فوجدتــه كمــا ذكــر‬\n     ‫املدعــي كمــا جــرى االطــاع علــى خطــاب مديــر قســم احلــوادث بشــأن‬\n     ‫تقديــر قيمــة املركبــة الصــادر مــن شــعبة مــرور محافظــة ينبــع املبنــي‬\n     ‫علــى خطــاب رئيــس طائفــة معــارض الســيارات بينبــع ونــص احلاجــة منــه‬\n     ‫أســم الســائق نــوع الســيارة كــورال صنــع عــام ‪2008‬م رقــم اللوحــة ‪....‬‬\n     ‫الفــرق بــن قيمــة الســيارة قبــل احلــادث وبعــده تقــدر مببلــغ واحــد وثالثــن‬\n     ‫ألــف ريــال فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة وحيــث أن جانــب‬\n     ‫املدعــي أقــوى مــن جانــب املدعــى عليــه ملــا قدمــه مــن بينــات وحيــث أن‬\n     ‫اليمــن تشــرع يف جانــب أقــوى املتداعــن كمــا قــرر ذلــك ابــن تيميــة‬\n     ‫رحمــه اهلل ونظــرا ملــا قــرر ســماحة الشــيخ ابــن إبراهيــم رحمــه يف قولــه ‪:‬‬\n     ‫(و إذا لــم تثبــت الدعــوى ببينــه وال اقــرار و وجــدت القرائــن القويــة الدالــة‬\n     ‫علــى صــدق الدعــوى فتقــوى بيمــن املدعــي) ينظــر التعميــم الصــادر‬\n     ‫مــن ســماحته برقــم ‪ 17‬بتاريــخ ‪1380/1/18‬ه ـ (ص‪ )128‬مــن كتــاب‬\n     ‫األنظمــة و اللوائــح ‪ ،‬وحيــث حلــف املدعــي اليمــن املتممــة لبينتــه لذلــك‬\n     ‫كلــه فقــد حكمــت علــى املدعــى عليــه أن يدفــع للمدعــي مبلــغ واحــد‬\n     ‫وثالثــن ألــف ريــال وبعــرض احلكــم علــى الطرفــن قــرر املدعــي رضــاه‬\n     ‫وقناعتــه باحلكــم وأمــا املدعــى عليــه فلــم يقنــع بــه وطلــب متيــزه بــدون‬\n     ‫الئحــة اعتراضيــة و أجيــب لطلبــه وســيتم رفــع كامــل املعاملــة إلــى‬\n     ‫محكمــة االســتئناف مبكــة املكرمــة لتدقيــق احلكــم وبــاهلل التوفيــق‬\n\n\n‫‪89‬‬\n\f‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪1434/10/21‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائية الســابعة يف محكمة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪ 342320456‬وتاريــخ‬\n‫‪1434/11/4‬ه ـ املرفــق بهــا الصــك الصادر من فضيلة الشــيخ‪ /‬القاضي‬\n‫باحملكمــة العامــة بينبــع برقــم ‪ 34338542‬وتاريــخ ‪1434/10/22‬ه ـ‬\n‫املتضمــن دعــوى‪ /‬ضــد‪( /‬نيبالــي اجلنســية) املتهــم يف حــادث مــروري‪،‬‬\n‫احملكــوم فيــه مبــا دون بباطــن الصــك ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪90‬‬\n\f91\n\f92\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":85,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4064a62dd304b351ee7253f36cdcbc20287e9eaaa79672bcec0676cbe3c7a99d","normalized_text_hash":"4726ceea58b9fb182fee620ae1b72c9b2fc6979f3f9fe07878fdf6b2187831a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p85-34338542"}]$archive_payload$::jsonb AS data)
